func defaultMasterPortForEngine(engineType string) int {
	switch normalizeMasterEngineType(engineType) {
	case "mongodb":
		return 27017
	case "mysql":
		return 3306
	case "clickhouse":
		return 9000
	default:
		return 5432
	}
}

