func normalizeEngineName(raw string) string {
	switch strings.ToLower(strings.TrimSpace(raw)) {
	case "mongodb", "mongo":
		return "mongodb"
	case "clickhouse", "ch":
		return "clickhouse"
	case "mysql", "mariadb":
		return "mysql"
	default:
		return "postgresql"
	}
}
